#include <iostream>
using namespace std;
int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= 2 * n - 1; ++i) {
        for (int j = 1; j <= 2 * n - 1; ++j) {
            if (i + j == n + 1 || i + j == 3 * n - 1)
                cout << '+';
            else if (i - j == n - 1 || j - i == n - 1)
                cout << '+';
            else
                cout << '.';
        }
        cout << '\n';
    }
    return 0;
}
